source /opt/conda/etc/profile.d/conda.sh 2>/dev/null; conda activate research 2>/dev/null; python -I - <<'PY'
import json, re
for nb in ["submission/pipeline/trojan_feedback_pipeline.ipynb","TrojanGYM/ghost_portkey_trojangym.ipynb"]:
    print("="*70)
    print(nb)
    print("="*70)
    data=json.load(open(nb))
    imports=set(); pips=[]; shells=[]
    for c in data.get("cells",[]):
        if c.get("cell_type")!="code": continue
        src="".join(c.get("source",[]))
        for line in src.splitlines():
            s=line.strip()
            if s.startswith("!") or s.startswith("%"):
                if "pip" in s or "conda" in s: pips.append(s)
                else: shells.append(s)
            m=re.match(r'^\s*(?:import|from)\s+([a-zA-Z0-9_\.]+)',line)
            if m: imports.add(m.group(1).split('.')[0])
    print("IMPORTS:", sorted(imports))
    print("PIP/CONDA:")
    for p in pips: print("   ",p)
    print("SHELL/MAGIC:")
    for sh in shells: print("   ",sh)
PY

